/**
 * Notification Centre - send broadcast messages and review recent
 * notifications generated by the workflow.
 */

import { api } from '../../api.js';
import { icon } from '../../icons.js';
import {
  escapeHtml, timeAgo, emptyState, loaderHtml, toast, setLoading,
  showFormAlert, clearFieldErrors, statusLabel,
} from '../../ui.js';

let feed = [];

function render() {
  return `
    <div class="page-head">
      <div>
        <h2>Notification centre</h2>
        <p class="desc">Send announcements to all citizens or administrators - and audit every notification the system has raised.</p>
      </div>
      <div class="head-actions">
        <a class="btn btn-soft" href="#/notifications">${icon('bell')} My notifications</a>
      </div>
    </div>

    <div class="panel-grid">
      <div class="col-5">
        <div class="form-panel">
          <div class="flex-between" style="margin-bottom:18px">
            <div>
              <h3 style="font-size:1.05rem">Send a notification</h3>
              <div class="muted text-sm">Delivered instantly to recipients' in-app notification centre.</div>
            </div>
            <span class="icon-tile">${icon('megaphone')}</span>
          </div>

          <form id="broadcast-form" novalidate>
            <div class="field" data-field="audience">
              <label>Audience <span class="req">*</span></label>
              <select class="select" name="role">
                <option value="all">Everyone (citizens + administrators)</option>
                <option value="citizen">All citizens</option>
                <option value="admin">All administrators</option>
              </select>
              <span class="field-error"></span>
            </div>

            <div class="field" data-field="title">
              <label>Title <span class="req">*</span></label>
              <input class="input" name="title" placeholder="e.g. Cleanliness & Segregation Drive" maxlength="120" />
              <span class="field-error"></span>
            </div>

            <div class="field" data-field="message">
              <label>Message <span class="req">*</span><span class="hint">min. 10 characters</span></label>
              <textarea class="textarea" name="message" style="min-height:130px" placeholder="Write the announcement…"></textarea>
              <span class="field-error"></span>
            </div>

            <div class="flex-center wrap gap-8" style="margin-bottom:18px">
              <span class="text-sm muted">Quick templates:</span>
              <button type="button" class="chip" data-tpl="drive">Segregation drive</button>
              <button type="button" class="chip" data-tpl="truck">Schedule update</button>
              <button type="button" class="chip" data-tpl="thanks">Thank you</button>
            </div>

            <div class="form-actions">
              <button class="btn btn-primary" type="submit" id="send-btn">${icon('send')} Send notification</button>
            </div>
          </form>
        </div>

        <div class="card card-pad" style="margin-top:20px">
          <div class="flex-center" style="gap:12px">
            <span class="icon-tile amber">${icon('zap')}</span>
            <div>
              <div class="strong text-sm">Automatic notifications</div>
              <div class="text-sm muted">The system already notifies administrators when citizens register, report waste, or send messages; and notifies citizens when complaints are updated or resolved.</div>
            </div>
          </div>
        </div>
      </div>

      <div class="col-7">
        <div class="card">
          <div class="card-head">
            <div><h3>Recent notifications</h3><div class="sub">Latest 60 across all users</div></div>
            <button class="btn btn-ghost btn-sm" id="refresh-feed">${icon('refresh')} Refresh</button>
          </div>
          <div class="table-wrap">
            <table class="table">
              <thead><tr><th>Recipient</th><th>Title</th><th>Message</th><th>Type</th><th>When</th></tr></thead>
              <tbody id="feed-body"><tr><td colspan="5">${loaderHtml('Loading…')}</td></tr></tbody>
            </table>
          </div>
        </div>
      </div>
    </div>`;
}

async function loadFeed() {
  const body = document.getElementById('feed-body');
  if (!body) return;
  try {
    const data = await api.get('/admin/notifications');
    feed = data.notifications || [];
  } catch (err) {
    toast(err.message, 'error');
    body.innerHTML = `<tr><td colspan="5">${emptyState({ iconName: 'alert-circle', title: 'Could not load feed', text: err.message })}</td></tr>`;
    return;
  }

  if (!feed.length) {
    body.innerHTML = `<tr><td colspan="5">${emptyState({ iconName: 'bell', title: 'No notifications yet', text: 'Notifications appear here as citizens report and administrators act.' })}</td></tr>`;
    return;
  }

  body.innerHTML = feed.map((n) => `
    <tr>
      <td>
        <div class="cell-title">${escapeHtml(n.user_name)}</div>
        <div class="cell-sub">${escapeHtml(n.user_role)}</div>
      </td>
      <td><div class="cell-title" style="font-size:.86rem">${escapeHtml(n.title)}</div>${n.report_code ? `<div class="cell-sub">${escapeHtml(n.report_code)}</div>` : ''}</td>
      <td class="cell-sub" style="max-width:320px">${escapeHtml(n.message.length > 120 ? n.message.slice(0, 119) + '…' : n.message)}</td>
      <td><span class="badge ${n.is_read ? 'badge-resolved' : 'badge-pending'}"><span class="dot"></span>${n.is_read ? 'Read' : 'Unread'}</span></td>
      <td class="cell-sub">${timeAgo(n.created_at)}</td>
    </tr>`).join('');
}

const TEMPLATES = {
  drive: {
    title: 'Sunday segregation drive',
    message: 'Please segregate wet and dry waste before 7 AM on Sunday. Collection trucks will arrive zone-wise and recycled material will be picked up separately.',
  },
  truck: {
    title: 'Collection schedule update',
    message: 'Due to road work, today\'s collection in your zone will begin 90 minutes later than usual. Please keep bins covered until the truck arrives.',
  },
  thanks: {
    title: 'Thank you for keeping the city clean',
    message: 'Your reports helped clear multiple dumping spots this week. Keep reporting and let us maintain a cleaner, healthier neighbourhood together.',
  },
};

function mount(root) {
  loadFeed();

  document.querySelectorAll('[data-tpl]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const tpl = TEMPLATES[btn.dataset.tpl];
      const form = document.getElementById('broadcast-form');
      form.elements.title.value = tpl.title;
      form.elements.message.value = tpl.message;
      clearFieldErrors(form);
      toast('Template applied.', 'info');
    });
  });

  document.getElementById('refresh-feed').addEventListener('click', loadFeed);

  const form = document.getElementById('broadcast-form');
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    clearFieldErrors(form);
    const role = form.elements.role.value;
    const title = form.elements.title.value.trim();
    const message = form.elements.message.value.trim();
    let ok = true;
    if (title.length < 3) { setErr('title', 'Title must be at least 3 characters.'); ok = false; }
    if (message.length < 10) { setErr('message', 'Message must be at least 10 characters.'); ok = false; }
    if (!ok) { showFormAlert(form, 'Please complete the highlighted fields.', 'error'); return; }

    function setErr(name, msg) {
      const field = form.querySelector(`[data-field="${name}"]`);
      field.classList.add('invalid');
      const err = field.querySelector('.field-error');
      if (err) err.textContent = msg;
    }

    const btn = document.getElementById('send-btn');
    setLoading(btn, true, 'Sending…');
    try {
      const data = await api.post('/admin/notifications/broadcast', { role, title, message });
      toast(data.message, 'success', 'Notification sent');
      form.elements.title.value = '';
      form.elements.message.value = '';
      await loadFeed();
    } catch (err) {
      showFormAlert(form, err.message, 'error');
    } finally {
      setLoading(btn, false);
    }
  });
}

export default { render, mount };
